  motor_init();

  motor_set_power(-10);
  ASSERT_EQ(motor_power(), 0);
  ASSERT_PIN(11, LOW);

  motor_set_power(128);
  ASSERT_EQ(motor_power(), 128);

  motor_set_power(300);
  ASSERT_EQ(motor_power(), 255);
  ASSERT_PIN(11, HIGH);
